node -e "
const XLSX = require('xlsx');

const wb = XLSX.readFile('env/testbed/data/order_summary.xlsx');
const lines = [];

for (const sheetName of wb.SheetNames) {
  lines.push('========================================');
  lines.push('Sheet: ' + sheetName);
  lines.push('========================================');

  const ws = wb.Sheets[sheetName];
  const range = XLSX.utils.decode_range(ws['!ref']);

  lines.push('Range: ' + ws['!ref'] + ' (' + (range.e.r - range.s.r + 1) + ' rows x ' + (range.e.c - range.s.c + 1) + ' cols)');
  lines.push('');

  // Cell-by-cell dump
  lines.push('--- Cell Contents ---');
  for (let r = range.s.r; r <= range.e.r; r++) {
    for (let c = range.s.c; c <= range.e.c; c++) {
      const addr = XLSX.utils.encode_cell({ r, c });
      const cell = ws[addr];
      if (cell) {
        const type = cell.t === 's' ? 'string' : cell.t === 'n' ? 'number' : cell.t === 'b' ? 'boolean' : cell.t;
        lines.push(addr + '  [' + type + ']  ' + cell.v);
      }
    }
  }

  lines.push('');

  // Tabular view
  lines.push('--- Tabular View ---');
  const csv = XLSX.utils.sheet_to_csv(ws);
  lines.push(csv);
  lines.push('');
}

const output = lines.join('\n');
require('fs').writeFileSync('env/testbed/data/order_summary_extracted.txt', output);
console.log(output);
console.log('\\n✅ Saved to env/testbed/data/order_summary_extracted.txt');
"
